import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage();

const requests = [];
page.on('request', (req) => {
  if (req.url().includes('/catalog')) {
    requests.push({ url: req.url(), time: Date.now() });
  }
});

await page.goto('http://localhost:3100/');

// Give the viewport-visible links a moment to prefetch.
await page.waitForTimeout(1500);

const prefetchCount = requests.length;
console.log(`Prefetch requests observed before click: ${prefetchCount}`);
requests.forEach((r) => console.log('  ', r.url));

// Watch whether the loading fallback text ever appears after click.
let sawLoadingText = false;
const checkInterval = setInterval(async () => {
  try {
    const text = await page.locator('main').innerText();
    if (text.includes('Loading category')) sawLoadingText = true;
  } catch {}
}, 20);

const clickStart = Date.now();
await page.getByRole('link', { name: 'Products on sale' }).click();
await page.waitForSelector('h2:has-text("Products on sale")', { timeout: 5000 });
const clickEnd = Date.now();
clearInterval(checkInterval);

console.log(`Time from click to heading rendered: ${clickEnd - clickStart}ms`);
console.log(`Loading fallback text observed at any point: ${sawLoadingText}`);

const bodyText = await page.locator('main').innerText();
console.log('Final rendered content:\n', bodyText);

await browser.close();

